 1| /**
 2|  * check-stock: one of the two checks that run side by side. It lists every
 3|  * item the shelf cannot fill.
 4|  *
 5|  * Example: 6 desk lamps ordered, 4 on the shelf → `stockOk = false`,
 6|  * `shortSkus = ['DESK-LAMP']`.
 7|  */
 8| import { STOCK } from '../../data/stock.mjs';
 9| 
10| export const purpose = 'Check that the shelf holds every item in the quantity ordered.';
11| 
12| /** @param {any} scope */
13| export function run(scope) {
14|   const short = [];
15|   for (const line of scope.pricedLines) {
16|     if ((STOCK[line.sku] ?? 0) < line.qty) short.push(line.sku);
17|   }
18|   scope.stockOk = short.length === 0;
19|   scope.shortSkus = short;
20| }
