 1| /**
 2|  * start-lines: sets up the loop that prices the order one line at a time.
 3|  *
 4|  * Why a loop of steps and not a `for` inside one step: each line's price is
 5|  * then its own step in the run, and a wrong line can be found by itself.
 6|  * Example: two lines → `lineIndex = 0`, `lineCount = 2`, `subtotal = 0`.
 7|  */
 8| 
 9| export const purpose = 'Start the line loop: first line, empty totals.';
10| 
11| /** @param {any} scope */
12| export function run(scope) {
13|   scope.lineIndex = 0;
14|   scope.lineCount = scope.lines.length;
15|   scope.pricedLines = [];
16|   scope.subtotal = 0;
17|   scope.totalWeight = 0;
